CREATE OR REPLACE FUNCTION public.is_lana_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM auth.users WHERE id=auth.uid() AND lower(email)='lanabeatriz929@gmail.com' AND email_confirmed_at IS NOT NULL); $$;
REVOKE ALL ON FUNCTION public.is_lana_admin() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_lana_admin() TO anon, authenticated;
ALTER TABLE public.analises ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.feedbacks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.concorrentes ENABLE ROW LEVEL SECURITY;
GRANT INSERT ON public.analises TO anon, authenticated;
GRANT SELECT, UPDATE, DELETE ON public.analises TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.feedbacks, public.concorrentes TO authenticated;
GRANT ALL ON public.analises, public.feedbacks, public.concorrentes TO service_role;
CREATE POLICY lana_manage_analises ON public.analises FOR ALL TO authenticated USING(public.is_lana_admin()) WITH CHECK(public.is_lana_admin());
CREATE POLICY visitor_save_analysis ON public.analises FOR INSERT TO anon, authenticated WITH CHECK (nota_geral BETWEEN 0 AND 100 AND dias_followup=7 AND followup_enviado=false AND data_followup=current_date+7 AND (consentimento=true OR (nome_dono IS NULL AND whatsapp IS NULL)));
CREATE POLICY lana_manage_feedbacks ON public.feedbacks FOR ALL TO authenticated USING(public.is_lana_admin()) WITH CHECK(public.is_lana_admin());
CREATE POLICY lana_manage_competitors ON public.concorrentes FOR ALL TO authenticated USING(public.is_lana_admin()) WITH CHECK(public.is_lana_admin());
CREATE OR REPLACE FUNCTION public.analysis_by_token(p_token uuid) RETURNS TABLE(id uuid,nome_hamburgueria text,nota_geral integer,numeros jsonb) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT id,nome_hamburgueria,nota_geral,numeros FROM public.analises WHERE token=p_token; $$;
REVOKE ALL ON FUNCTION public.analysis_by_token(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.analysis_by_token(uuid) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.submit_feedback(p_token uuid,p_momento text,p_utilidade integer DEFAULT NULL,p_sugestoes text DEFAULT NULL,p_aplicou boolean DEFAULT NULL,p_antes integer DEFAULT NULL,p_depois integer DEFAULT NULL,p_comentario text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE aid uuid; BEGIN SELECT id INTO aid FROM public.analises WHERE token=p_token FOR UPDATE; IF aid IS NULL THEN RAISE EXCEPTION 'Link inválido'; END IF; IF p_momento NOT IN ('imediato','retorno') OR (p_momento='imediato' AND (p_utilidade IS NULL OR p_utilidade NOT BETWEEN 1 AND 5)) OR (p_momento='retorno' AND p_aplicou IS NULL) OR p_antes<0 OR p_depois<0 OR length(p_sugestoes)>3000 OR length(p_comentario)>3000 THEN RAISE EXCEPTION 'Resposta inválida'; END IF; IF EXISTS(SELECT 1 FROM public.feedbacks WHERE analise_id=aid AND momento=p_momento) THEN RAISE EXCEPTION 'Pesquisa já respondida'; END IF; INSERT INTO public.feedbacks(analise_id,momento,utilidade,sugestoes_aplicadas,aplicou_mudancas,pedidos_semana_antes,pedidos_semana_depois,comentario) VALUES(aid,p_momento,p_utilidade,p_sugestoes,p_aplicou,p_antes,p_depois,p_comentario); END; $$;
REVOKE ALL ON FUNCTION public.submit_feedback(uuid,text,integer,text,boolean,integer,integer,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.submit_feedback(uuid,text,integer,text,boolean,integer,integer,text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.save_competitors(p_token uuid,p_rows jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE aid uuid; item jsonb; BEGIN SELECT id INTO aid FROM public.analises WHERE token=p_token FOR UPDATE; IF aid IS NULL THEN RAISE EXCEPTION 'Link inválido'; END IF; IF jsonb_typeof(p_rows)<>'array' OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 3 THEN RAISE EXCEPTION 'Máximo de 3 concorrentes'; END IF; IF EXISTS(SELECT 1 FROM public.concorrentes WHERE analise_id=aid) THEN RAISE EXCEPTION 'Comparação já salva'; END IF; FOR item IN SELECT value FROM jsonb_array_elements(p_rows) LOOP IF (item->>'nota_geral')::integer NOT BETWEEN 0 AND 100 OR length(item->>'nome')>200 THEN RAISE EXCEPTION 'Concorrente inválido'; END IF; INSERT INTO public.concorrentes(analise_id,nome,nota_geral,numeros,notas_criterios) VALUES(aid,item->>'nome',(item->>'nota_geral')::integer,item->'numeros',item->'notas_criterios'); END LOOP; END; $$;
REVOKE ALL ON FUNCTION public.save_competitors(uuid,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.save_competitors(uuid,jsonb) TO anon,authenticated;